content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "FABS",
      "desc": "Federal Assistance Broker System – manages financial assistance data submissions",
      "attributes": "Historical Data, System Rules"
    },
    {
      "name": "Historical Data",
      "desc": "old records of data"
    },
    {
      "name": "System Rules",
      "desc": "set of rules that determines the regulations for submission and data handling"
    },
    {
      "name": "DABS",
      "desc": "Data Act Broker System – related system for managing different financial data sets",
      "attributes": "System Rules"
    },
    {
      "name": "FDPS",
      "desc": "Federal Procurement Data System – database of government contract and procurement data",
      "attributes": "System Rules"
    },
    {
      "name": "Submission",
      "desc": "a file or dataset uploaded to report financial data",
      "attributes": "Status, Deadline, Submission Data, Notification"
    },
    {
      "name": "Submission Data",
      "desc": "Included in Submission by Agency"
    },
    {
      "name": "Status",
      "desc": "the state of the submission"
    },
    {
      "name": "Deadline",
      "desc": "time at which the submission is due"
    },
    {
      "name": "Notification",
      "desc": "a reminder to a submitting party that certain data should be submitted in time"
    },
    {
      "name": "Agency User",
      "desc": "a government employee submitting data for their agency"
    },
    {
      "name": "Published Data",
      "desc": "data available to users of the broker system"
    },
    {
      "name": "Broker",
      "desc": "Shared Frontend to FABS and DABS via which Users access the system",
      "attributes": "System Performance, Design"
    },
    {
      "name": "System Performance",
      "desc": "Metrics that determine the performance and functionality of the system"
    },
    {
      "name": "Design",
      "desc": "the design of the Broker"
    },
    {
      "name": "Broker User",
      "desc": "someone accessing the services of the broker system"
    },
    {
      "name": "Developer",
      "desc": "a technical member who implements and maintains functions of the broker system"
    },
    {
      "name": "Data User",
      "desc": "Someone who accesses official financial data"
    },
    {
      "name": "Test",
      "desc": "a unit that determines the functionality of the Design",
      "attributes": "Result"
    },
    {
      "name": "Owner",
      "desc": "stakeholder in charge of product direction and improvement"
    },
    {
      "name": "UI Designer",
      "desc": "shapes the design of the broker"
    },
    {
      "name": "Field Derivation",
      "desc": "analytical data derived from the system"
    },
    {
      "name": "Tester",
      "desc": "examines functionality of Field Derivation"
    }
  ]
}
```

Here are the associations:
```json
{
  "associations": [
    {
      "from": "FABS",
      "to": "Published Data",
      "desc": "FABS feeds data into Published Data"
    },
    {
      "from": "DABS",
      "to": "Published Data",
      "desc": "DABS feeds data into Published Data"
    },
    {
      "from": "Agency User",
      "to": "System Rules",
      "desc": "Agency User has to follow System Rules when forming submissions"
    },
    {
      "from": "Broker",
      "to": "FABS",
      "desc": "Broker poses as frontend to FABS"
    },
    {
      "from": "Broker",
      "to": "DABS",
      "desc": "Broker poses as frontend to DABS"
    },
    {
      "from": "Broker User",
      "to": "Submission",
      "desc": "Broker User makes and tracks Submission"
    },
    {
      "from": "Developer",
      "to": "System Performance",
      "desc": "Developer oversees System Performance"
    },
    {
      "from": "Agency User",
      "to": "Submission",
      "desc": "Agency User makes and tracks Submission"
    },
    {
      "from": "Data User",
      "to": "Published Data",
      "desc": "Data User accesses Published Data"
    },
    {
      "from": "UI Designer",
      "to": "Design",
      "desc": "UI Designer creates Design"
    },
    {
      "from": "Test",
      "to": "Design",
      "desc": "Test evaluates quality of Design"
    },
    {
      "from": "Owner",
      "to": "Test",
      "desc": "Owner monitors the Result of a Test"
    },
    {
      "from": "UI Designer",
      "to": "Test",
      "desc": "UI Designer performs a Test"
    },
    {
      "from": "Broker User",
      "to": "Test",
      "desc": "Broker takes part in a Test"
    },
    {
      "from": "Submission",
      "to": "Broker",
      "desc": "Submission is put into Broker"
    },
    {
      "from": "Broker",
      "to": "FABS",
      "desc": "Broker forwards accesses to FABS"
    },
    {
      "from": "Broker",
      "to": "DABS",
      "desc": "Broker forwards accesses to DABS"
    },
    {
      "from": "FDPS",
      "to": "Field Derivation",
      "desc": "FDPS delivers Field Derivation"
    },
    {
      "from": "Tester",
      "to": "Field Derivation",
      "desc": "Tester examines Field Derivation"
    },
    {
      "from": "Notification",
      "to": "Agency User",
      "desc": "Notification is sent to Agency User"
    }
  ]
}
```
